const dns = require('dns');
const crypto = require('crypto');
const http = require('http');
const vm = require('vm');

const ENCRYPTION_KEY = crypto.randomBytes(32);
const IV_LENGTH = 16;

function encrypt(text) {
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv('aes-256-cbc', ENCRYPTION_KEY, iv);
  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  return iv.toString('hex') + ':' + encrypted;
}

function decrypt(text) {
  const parts = text.split(':');
  const iv = Buffer.from(parts[0], 'hex');
  const decipher = crypto.createDecipheriv('aes-256-cbc', ENCRYPTION_KEY, iv);
  let decrypted = decipher.update(parts[1], 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

const dnsCache = new Map();

class DNSRecord {
  constructor(hostname, addresses, ttl) {
    this.hostname = hostname;
    this.addresses = addresses;
    this.ttl = ttl;
    this.timestamp = Date.now();
  }

  isExpired() {
    return (Date.now() - this.timestamp) > (this.ttl * 1000);
  }
}

class TemplateEngine {
  constructor() {
    this.helpers = {
      formatDate: (ts) => new Date(ts).toISOString(),
      uppercase: (s) => String(s).toUpperCase(),
      json: (obj) => JSON.stringify(obj, null, 2)
    };
  }

  render(template, context) {
    const sandbox = { ...context, helpers: this.helpers };
    const processed = template.replace(/\{\{([^}]+)\}\}/g, (match, expr) => {
      try {
        const script = new vm.Script(`__result = ${expr}`);
        const ctx = vm.createContext(sandbox);
        script.runInContext(ctx);
        return ctx.__result !== undefined ? String(ctx.__result) : '';
      } catch (e) {
        return match;
      }
    });
    return processed;
  }
}

const templateEngine = new TemplateEngine();

const RESPONSE_TEMPLATES = {
  success: '<div class="result"><h3>DNS Lookup: {{hostname}}</h3><p>Addresses: {{helpers.json(addresses)}}</p><p>TTL: {{ttl}}s</p><p>Cached: {{helpers.formatDate(timestamp)}}</p></div>',
  error: '<div class="error"><h3>Lookup Failed</h3><p>Host: {{hostname}}</p><p>Error: {{errorMessage}}</p></div>',
  list: '<div class="cache"><h3>Cached Records</h3><ul>{{entries}}</ul></div>'
};

function resolveAndCache(hostname, callback) {
  if (dnsCache.has(hostname)) {
    const encrypted = dnsCache.get(hostname);
    const data = JSON.parse(decrypt(encrypted));
    const record = new DNSRecord(data.hostname, data.addresses, data.ttl);
    record.timestamp = data.timestamp;
    if (!record.isExpired()) {
      return callback(null, record);
    }
    dnsCache.delete(hostname);
  }

  dns.resolve4(hostname, { ttl: true }, (err, addresses) => {
    if (err) return callback(err, null);
    const ttl = addresses[0] && addresses[0].ttl ? addresses[0].ttl : 300;
    const addrs = addresses.map(a => typeof a === 'object' ? a.address : a);
    const record = new DNSRecord(hostname, addrs, ttl);
    const serialized = JSON.stringify(record);
    dnsCache.set(hostname, encrypt(serialized));
    callback(null, record);
  });
}

function buildResponseFromRecord(record) {
  return templateEngine.render(RESPONSE_TEMPLATES.success, record);
}

function buildErrorResponse(hostname, error) {
  return templateEngine.render(RESPONSE_TEMPLATES.error, {
    hostname: hostname,
    errorMessage: error.message || String(error)
  });
}

function buildCustomResponse(userTemplate, record) {
  return templateEngine.render(userTemplate, record);
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (url.pathname === '/resolve' && req.method === 'GET') {
    const hostname = url.searchParams.get('host');
    const format = url.searchParams.get('format');

    if (!hostname || !/^[a-zA-Z0-9][a-zA-Z0-9.-]+[a-zA-Z]{2,}$/.test(hostname)) {
      res.writeHead(400, { 'Content-Type': 'text/html' });
      res.end('<p>Invalid hostname</p>');
      return;
    }

    resolveAndCache(hostname, (err, record) => {
      res.writeHead(200, { 'Content-Type': 'text/html' });
      if (err) {
        res.end(buildErrorResponse(hostname, err));
      } else if (format) {
        res.end(buildCustomResponse(format, record));
      } else {
        res.end(buildResponseFromRecord(record));
      }
    });
  } else if (url.pathname === '/cache' && req.method === 'GET') {
    const entries = [];
    for (const [host, encrypted] of dnsCache) {
      try {
        const data = JSON.parse(decrypt(encrypted));
        entries.push(`<li>${host}: ${data.addresses.join(', ')}</li>`);
      } catch (e) {
        entries.push(`<li>${host}: [decryption error]</li>`);
      }
    }
    const html = templateEngine.render(RESPONSE_TEMPLATES.list, { entries: entries.join('') });
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(html);
  } else {
    res.writeHead(404);
    res.end('Not Found');
  }
});

server.listen(3000, () => console.log('DNS Resolver running on port 3000'));

module.exports = { server, encrypt, decrypt, templateEngine, resolveAndCache };
